import { NativeImage, parseColor } from "@opentui/core";

/** True-alpha RGBA PNG crops from the local 8-frame zero-axe-blinking.gif. */
const ZERO_AXE_FRAME_PNGS = [
  '',
  '',
  '',
  '',
  '',
  '',
  '',
  ''
] as const;

const ZERO_AXE_FRAME_BYTES = ZERO_AXE_FRAME_PNGS.map((frame) => Buffer.from(frame, "base64"));
export const ZERO_AXE_FRAME_DURATIONS = [2800, 40, 40, 120, 40, 40, 920, 40] as const;
export const ZERO_AXE_WIDTH = 29;
export const ZERO_AXE_HEIGHT = 18;

/** Decode and flatten the transparent mascot onto the active terminal canvas. */
export function createZeroAxeImages(canvas: string): NativeImage[] {
  const [red, green, blue] = parseColor(canvas).toInts();
  return ZERO_AXE_FRAME_BYTES.map((bytes) => {
    const source = NativeImage.decode(bytes);
    try {
      const raw = source.raw();
      const pixels = new Uint8Array(raw.width * raw.height * 4);
      for (let y = 0; y < raw.height; y++) {
        for (let x = 0; x < raw.width; x++) {
          const offset = y * raw.stride + x * 4;
          const target = (y * raw.width + x) * 4;
          const alpha = raw.data[offset + 3]! / 255;
          pixels[target] = Math.round(raw.data[offset]! * alpha + red * (1 - alpha));
          pixels[target + 1] = Math.round(raw.data[offset + 1]! * alpha + green * (1 - alpha));
          pixels[target + 2] = Math.round(raw.data[offset + 2]! * alpha + blue * (1 - alpha));
          pixels[target + 3] = 255;
        }
      }
      return NativeImage.fromRgba(pixels, raw.width, raw.height);
    } finally {
      source.dispose();
    }
  });
}
